"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4267],{44267:n=>{n.exports=JSON.parse('{"id":"base-10","slug":"base-10","trackId":"base","order":11,"title":"Биржи и иллюзия лёгких денег","subtitle":"Понятные правила защиты капитала","estimatedMinutes":9,"access":"free","quizCount":3,"blueprintCount":0,"trainerIds":["HUB-CALC-05"],"markdown":"Урок 10 \xb7 6 мин \\n\\n## Биржи и торговля \\n\\nИллюзия \xabлёгких\xbb денег \\n\\nПосле того как человек научился покупать криптовалюту, следующий шаг кажется очевидным: \\n\\nа можно ли на ней зарабатывать? \\n\\nТы открываешь биржу. Перед тобой график цены. Кнопки Buy и Sell. Можно купить Bitcoin, продать ETH или открыть сделку на движение цены. \\n\\nВсё выглядит очень доступно. Именно здесь возникает первая ловушка: \\n\\nоткрыть сделку легко. Стабильно зарабатывать на торговле — очень сложно. \\n\\n### Что такое биржа \\n\\nБиржа — это площадка, где встречаются покупатели и продавцы. Можно представить её как большой электронный рынок. Один человек хочет купить Bitcoin. Другой — продать. \\n\\nБиржа соединяет их и проводит сделку. На бирже можно: \\n- купить криптовалюту; \\n- продать её; \\n- обменять один актив на другой; \\n- заранее указать цену покупки или продажи; \\n- использовать более сложные инструменты для торговли на рост и падение. \\n\\nДля новичка этого понимания достаточно. Биржа — это инфраструктура . Она даёт доступ к рынку, но не даёт навыка зарабатывать на нём. \\n\\n### Купить криптовалюту и торговать — не одно и то же \\n\\nЕсли ты купил Bitcoin и собираешься держать его несколько лет — это одна задача. Если ты пытаешься заработать на движении цены сегодня, завтра или на следующей неделе — уже другая. Во втором случае ты занимаешься трейдингом . Трейдеру приходится постоянно принимать решения: \\n- когда войти; \\n- каким объёмом; \\n- где закрыть прибыль; \\n- где признать ошибку; \\n- сколько денег можно потерять в одной сделке. \\n\\nПоэтому трейдинг — это не просто \xabкупить дешевле и продать дороже\xbb. Это система принятия решений в условиях, где заранее никто не знает, куда пойдёт цена. \\n\\n### Это территория профессионалов \\n\\nПредставь, что ты впервые пришёл в боксёрский зал. Тебе показали стойку. Научили нескольким ударам. Ты десять минут поработал по мешку. \\n\\nА потом тебя отправляют на ринг против Майка Тайсона. Звучит абсурдно. Но на финансовом рынке новичок часто делает примерно то же самое. По другую сторону сделки могут находиться: \\n- профессиональные трейдеры; \\n- крупные торговые компании; \\n- маркет-мейкеры; \\n- автоматические торговые системы; \\n- аналитические команды; \\n- участники с многолетним опытом и большим капиталом. \\n\\nПоэтому трейдинг правильнее воспринимать как отдельную профессию , а не как быстрый способ попробовать заработать. \\n\\n### Большинство частных трейдеров деньги теряет \\n\\nЭто важно понимать ещё до первой серьёзной сделки. В известном исследовании бразильского фьючерсного рынка среди людей, которые продолжали заниматься торговлей более 300 дней, 97% потеряли деньги . Это не означает, что ровно 97% всех трейдеров на всех рынках обязательно проигрывают. Но общий вывод очень простой: \\n\\nстабильно зарабатывать на краткосрочной торговле удаётся небольшому меньшинству. \\n\\nИ причина не только в том, что сложно понять направление цены. Нужно одновременно уметь управлять риском, капиталом, статистикой и собственным поведением. \\n\\n### Что новичку нужно знать о бирже \\n\\nДля общего развития достаточно нескольких базовых вещей. \\n\\n#### Спот \\n\\nЭто обычная покупка актива. Купил 1 ETH — у тебя появился 1 ETH на балансе. Цена выросла — актив стоит дороже. Цена упала — дешевле. \\n\\n#### Ордер \\n\\nЭто инструкция бирже. Например: \\n\\n\xabкупи Bitcoin, если цена опустится до $60 000\xbb. \\n\\nБиржа сама выполнит заявку, если цена дойдёт до указанного уровня. \\n\\n#### Рыночная цена \\n\\nЦена, по которой актив можно купить или продать прямо сейчас. \\n\\n#### Стоп-лосс \\n\\nЭто заранее заданная цена, при которой сделка закрывается, если рынок пошёл против тебя. Его задача — заранее ограничить размер ошибки. \\n\\n#### Фьючерсы \\n\\nЭто более сложный инструмент. С его помощью можно пытаться зарабатывать как на росте, так и на падении цены. Также во фьючерсах часто используется кредитное плечо . \\n\\n### Что такое кредитное плечо \\n\\nКредитное плечо позволяет открыть позицию больше, чем сумма твоих собственных денег. Например: \\n\\nу тебя есть $1 000. С плечом 10x можно открыть позицию примерно на $10 000. Если рынок движется на 1% в твою сторону, результат для твоего капитала будет значительно сильнее. Но если цена идёт против тебя — убыток увеличивается так же быстро. \\n\\nПоэтому пока нет опыта, плечо лучше воспринимать не как способ увеличить прибыль, а как увеличитель риска . Можно сравнить его со скоростью автомобиля. Высокая скорость позволяет двигаться быстрее. Но при ошибке последствия становятся намного серьёзнее. \\n\\nУ тебя $1 000. Берёшь плечо Плечо 10x \xb7 сделка на $10\xa0000 Цена пошла −5% \\n\\n$500 \\n\\nосталось на счёте Цена сдвинулась на 5%, а твои деньги — на 50%. При 10x всё сгорит, если цена пойдёт против тебя на 10%. \\n\\nУпрощённо, без комиссий: биржа закроет сделку ещё раньше. Плечо увеличивает не прибыль, а риск. \\n\\n### Трейдинг — это бизнес, а не набор ставок \\n\\nПрофессионального трейдера правильнее сравнивать не с игроком в казино, а с человеком, который управляет бизнесом. В бизнесе есть: \\n- доход; \\n- расходы; \\n- риск; \\n- статистика; \\n- правила; \\n- план; \\n- контроль капитала. \\n\\nВ трейдинге должно быть то же самое. Нужна понятная торговая система. Нужно заранее ограничивать риск. Нужно вести статистику. \\n\\nНужно понимать, при каких условиях стратегия работает, а при каких — нет. И главное — соблюдать собственные правила. Если сегодня ты рискуешь 1% капитала, а после нескольких убытков решаешь рискнуть 20%, у тебя уже нет системы. \\n\\n### Финансовый контроль важнее одной удачной сделки \\n\\nНовичок обычно думает: \\n\\n\xabкуда сейчас пойдёт цена?\xbb \\n\\nПрофессионал обязательно думает ещё об одном: \\n\\n\xabчто произойдёт с моим капиталом, если я ошибусь?\xbb \\n\\nМожно несколько раз неправильно определить направление рынка и при этом сохранить счёт, если каждый убыток заранее ограничен. И наоборот — можно долго торговать успешно, а затем одной слишком большой сделкой потерять значительную часть капитала. Поэтому профессиональная торговля строится не вокруг попытки всегда быть правым. Она строится вокруг контроля размера ошибки. \\n\\n### Психология — часть профессии \\n\\nТрейдинг очень быстро показывает привычки самого человека. Если человек нетерпелив в обычной жизни, ему сложно ждать хорошую сделку. Если тяжело признаёт ошибки — сложно закрыть убыточную позицию. Если постоянно хочется большего — сложно вовремя остановиться после прибыли. \\n\\nЕсли человек импульсивен — эта импульсивность почти наверняка появится и на бирже. Отсюда простая мысль: \\n\\nкак человек живёт, так он очень часто и торгует. \\n\\nВместе с деньгами на рынок человек приносит: \\n- страх; \\n- жадность; \\n- азарт; \\n- нетерпение; \\n- желание доказать свою правоту; \\n- попытку быстро вернуть потерянное; \\n- чрезмерную уверенность после нескольких удачных сделок. \\n\\nПсихологическая подготовка нужна не для того, чтобы перестать испытывать эмоции. Она нужна для того, чтобы эмоции не меняли заранее установленные правила . \\n\\n### Свобода требует дисциплины \\n\\nНа бирже почти никто не ограничивает твои решения. Можно открыть слишком большую позицию. Можно использовать большое плечо. Можно после нескольких убытков резко увеличить риск. \\n\\nТехнически биржа часто это позволит. Именно поэтому свобода на рынке работает только вместе с дисциплиной. Профессиональный трейдер создаёт ограничения себе сам: \\n- сколько можно потерять в одной сделке; \\n- сколько можно потерять за день; \\n- каким объёмом можно торговать; \\n- когда торговлю нужно остановить; \\n- какие сделки вообще нельзя открывать. \\n\\nСвобода без таких правил очень быстро превращается в завышенный риск. \\n\\n### Учиться нужно у профессионалов — но найти их сложно \\n\\nЕсли трейдинг — профессия, логично, что ему нужно учиться. Проблема в том, что вокруг торговли существует огромная индустрия людей, которые зарабатывают не торговлей, а продажей мечты о лёгких деньгах. Красивые машины. Скриншоты прибыльных сделок. \\n\\n\xab90% успешных сигналов\xbb. \xabСделаем из $1 000 миллион\xbb. \xabМоя стратегия никогда не ошибается\xbb. Новичку особенно сложно отличить реального профессионала от хорошего продавца. \\n\\nПоэтому смотреть нужно не на образ жизни человека, а на то, как он говорит о торговле . Хороший специалист способен объяснить: \\n- как устроена его система; \\n- какой риск он принимает; \\n- какие бывают убыточные периоды; \\n- когда стратегия не работает; \\n- как ведётся статистика; \\n- почему принимается конкретное решение. \\n\\nЕсли человек говорит только о прибыли и почти никогда не говорит о риске и убытках — это серьёзный повод насторожиться. \\n\\n### Самое главное \\n\\nКупить криптовалюту на бирже и профессионально торговать на ней — две совершенно разные задачи. Трейдинг требует одновременно развивать: \\n- знания; \\n- управление капиталом; \\n- контроль риска; \\n- статистику; \\n- дисциплину; \\n- психологическую устойчивость. \\n\\nСамая опасная особенность торговли заключается в том, что начать очень легко . Регистрация занимает несколько минут. Открытие сделки — несколько секунд. Но между умением нажать кнопку Buy и способностью стабильно зарабатывать существует примерно такая же разница, как между первым занятием в боксёрском зале и выходом на профессиональный ринг. \\n\\nПоэтому если торговля действительно интересна, относиться к ней стоит как к профессии: \\n\\nучиться, тренироваться, вести статистику, контролировать капитал и соблюдать правила. \\n\\nИ уже после этого имеет смысл переходить к практике и регистрации на бирже. \\n\\n### Проверь себя 1 / 3 \\n\\nЧто лучше всего описывает разницу между покупкой криптовалюты и трейдингом? \\n\\n\\n### Встроенные термины урока:\\n- **Фьючерс** — договор купить или продать что-то в будущем по цене, о которой договорились сегодня. По ценам фьючерсов видно, чего ждёт рынок: от курса нефти до решения ФРС по ставке. Это ожидание, а не прогноз — рынок ошибается регулярно\\n- **Кредитное плечо** — позиция больше твоих денег за счёт заёмных: с плечом 10x на $1 000 открываешь сделку на $10 000. Движение цены бьёт по деньгам в 10 раз сильнее — в обе стороны\\n\\n### Проверочный тест после урока (\xabПроверь себя\xbb):\\n**Вопрос 1: Что лучше всего описывает разницу между покупкой криптовалюты и трейдингом?**\\n- ⚪ Вариант 1: Разницы нет, это одно и то же\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 2: Покупка актива может быть долгосрочным решением, а трейдинг предполагает постоянные решения о входе, выходе и риске\\n- ⚪ Вариант 3: Трейдинг — это только покупка Bitcoin\\n\\n**Вопрос 2: Что делает кредитное плечо?**\\n- ⚪ Вариант 1: Гарантирует большую прибыль\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 2: Увеличивает размер позиции и одновременно усиливает как потенциальную прибыль, так и убыток\\n- ⚪ Вариант 3: Защищает позицию от падения рынка\\n\\n**Вопрос 3: Что ближе всего к профессиональному подходу в трейдинге?**\\n- ⚪ Вариант 1: Всегда стараться угадать направление рынка\\n- ⚪ Вариант 2: После убытка увеличивать размер следующей сделки\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 3: Заранее определять допустимый риск и соблюдать торговые правила\\n\\n\\n---","blueprints":[],"quiz":[{"id":"q-base-10-1","prompt":"Что лучше всего описывает разницу между покупкой криптовалюты и трейдингом?","options":[{"id":"base-10-1-1","label":"Разницы нет, это одно и то же","isCorrect":false,"feedback":"Неверно. Покупка актива может быть долгосрочным решением, а трейдинг предполагает постоянные решения о входе, выходе и риске"},{"id":"base-10-1-2","label":"Покупка актива может быть долгосрочным решением, а трейдинг предполагает постоянные решения о входе, выходе и риске","isCorrect":true,"feedback":"Верно. Покупка актива может быть долгосрочным решением, а трейдинг предполагает постоянные решения о входе, выходе и риске"},{"id":"base-10-1-3","label":"Трейдинг — это только покупка Bitcoin","isCorrect":false,"feedback":"Неверно. Покупка актива может быть долгосрочным решением, а трейдинг предполагает постоянные решения о входе, выходе и риске"}],"explanation":"Покупка актива может быть долгосрочным решением, а трейдинг предполагает постоянные решения о входе, выходе и риске","sourceRef":"CAPITAL_BASE:2269–2272 (Verbatim)"},{"id":"q-base-10-2","prompt":"Что делает кредитное плечо?","options":[{"id":"base-10-2-1","label":"Гарантирует большую прибыль","isCorrect":false,"feedback":"Неверно. Увеличивает размер позиции и одновременно усиливает как потенциальную прибыль, так и убыток"},{"id":"base-10-2-2","label":"Увеличивает размер позиции и одновременно усиливает как потенциальную прибыль, так и убыток","isCorrect":true,"feedback":"Верно. Увеличивает размер позиции и одновременно усиливает как потенциальную прибыль, так и убыток"},{"id":"base-10-2-3","label":"Защищает позицию от падения рынка","isCorrect":false,"feedback":"Неверно. Увеличивает размер позиции и одновременно усиливает как потенциальную прибыль, так и убыток"}],"explanation":"Увеличивает размер позиции и одновременно усиливает как потенциальную прибыль, так и убыток","sourceRef":"CAPITAL_BASE:2274–2277 (Verbatim)"},{"id":"q-base-10-3","prompt":"Что ближе всего к профессиональному подходу в трейдинге?","options":[{"id":"base-10-3-1","label":"Всегда стараться угадать направление рынка","isCorrect":false,"feedback":"Неверно. Заранее определять допустимый риск и соблюдать торговые правила"},{"id":"base-10-3-2","label":"После убытка увеличивать размер следующей сделки","isCorrect":false,"feedback":"Неверно. Заранее определять допустимый риск и соблюдать торговые правила"},{"id":"base-10-3-3","label":"Заранее определять допустимый риск и соблюдать торговые правила","isCorrect":true,"feedback":"Верно. Заранее определять допустимый риск и соблюдать торговые правила"}],"explanation":"Заранее определять допустимый риск и соблюдать торговые правила","sourceRef":"CAPITAL_BASE:2279–2282 (Verbatim)"}],"source":{"file":"00_FREE_GIFT_MakeCash_Crypto_And_Capital_Base_15_Lessons.md","sha256":"88a3efb162434bb8a9b3b000caee579d9c27005a8ea46ddf4ef9cafb50dc45cc","lineStart":2054,"lineEnd":2287}}')}}]);